def migrate_offering_terms(apps, schema_editor):
    Offering = apps.get_model("marketplace", "Offering")
    TermsOfService = apps.get_model("marketplace", "OfferingTermsOfService")
    UserOfferingConsent = apps.get_model("marketplace", "UserOfferingConsent")
    OfferingUser = apps.get_model("marketplace", "OfferingUser")

    # Find offerings that have either terms_of_service or terms_of_service_link
    offerings_with_tos = Offering.objects.filter(
        ~Q(terms_of_service="") | ~Q(terms_of_service_link="")
    )

    for offering in offerings_with_tos:
        TermsOfService.objects.create(
            offering=offering,
            terms_of_service=offering.terms_of_service or "",
            terms_of_service_link=offering.terms_of_service_link or "",
            version="1.0",
            is_active=True,
            requires_reconsent=True,
        )

        offering_user_ids = OfferingUser.objects.filter(offering=offering).values_list(
            "user_id", flat=True
        )

        # Create UserOfferingConsent for all OfferingUsers
        consents_to_create = [
            UserOfferingConsent(
                user_id=user_id,
                offering=offering,
                version="1.0",
            )
            for user_id in offering_user_ids
        ]

        if consents_to_create:
            UserOfferingConsent.objects.bulk_create(consents_to_create)


